export function getModelDocUrl(path: string): string | undefined {
  const entry = DOC_URL_CATALOG[path];
  if (!entry) {
    return undefined;
  }
  return typeof entry.docUrl === 'string' ? entry.docUrl : entry.docUrl[0];
}
